body.script:
(function () {
    var app = document.getElementById("app"), token = app.dataset.token, img = null;
    var $ = function (id) { return document.getElementById(id); };
    var tr = function (id) { return $("t_" + id).textContent; };
    if (!token || !$("cam")) return;
    function compress(file, cb) {
        var url = URL.createObjectURL(file), im = new Image();
        im.onload = function () {
            var k = Math.min(1, 1280 / Math.max(im.width, im.height)), c = document.createElement("canvas");
            c.width = Math.round(im.width * k); c.height = Math.round(im.height * k);
            c.getContext("2d").drawImage(im, 0, 0, c.width, c.height);
            URL.revokeObjectURL(url);
            cb(c.toDataURL("image/jpeg", 0.7).split(",")[1]);
        };
        im.src = url;
    }
    $("cam").onclick = $("again").onclick = function () { $("file").click(); };
    $("file").onchange = function (e) {
        var f = e.target.files[0]; e.target.value = "";
        if (!f) return;
        compress(f, function (b64) {
            img = b64; $("pv").src = "data:image/jpeg;base64," + b64; $("pv").hidden = false;
            $("cam").hidden = true; $("two").hidden = false; $("err").textContent = "";
        });
    };
    $("send").onclick = function () {
        if (!img) return;
        $("send").disabled = true; $("send").textContent = tr("sending");
        fetch("/navitta/r/upload", { method: "POST", headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ jsonrpc: "2.0", method: "call", params: { token: token, data: img, mime: "image/jpeg" } }) })
            .then(function (r) { return r.json(); })
            .then(function (j) {
                var res = j.result || {};
                if (res.ok) { $("two").hidden = true; $("pv").hidden = true; $("ok").hidden = false; return; }
                $("err").textContent = res.error === "expired" ? tr("expired") : tr("invalid");
                $("send").disabled = false; $("send").textContent = tr("send");
            })
            .catch(function () { $("err").textContent = tr("offline"); $("send").disabled = false; $("send").textContent = tr("send"); });
    };
})();
